"use strict";

const {App} = require("@slack/bolt");
const {randomUUID} = require("crypto");

module.exports = function(RED, createApp = options => new App(options)) {
    function formMetadata(view) {
        try {
            return JSON.parse(view.private_metadata);
        } catch (error) {
            return null;
        }
    }

    function SlackSocketNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;
        let app;
        let closed = false;
        const grants = new Map();

        function flowForm(view) {
            const metadata = formMetadata(view);
            const form = metadata && RED.nodes.getNode(metadata.formId);
            return form && form.socketId === node.id ? form : null;
        }

        node.openForm = async function(interactionId, formId, view) {
            const grant = grants.get(interactionId);
            grants.delete(interactionId);
            if (closed || !grant || grant.expires < Date.now() ||
                    view.callback_id !== "nrflow_" + formId || !app) {
                throw new Error("Slack form interaction expired");
            }
            const metadata = formMetadata(view);
            if (!metadata || metadata.formId !== formId || metadata.user !== grant.user ||
                    metadata.channel !== grant.channel || metadata.command !== grant.command) {
                throw new Error("Slack form interaction is invalid");
            }
            return app.client.views.open({trigger_id: grant.triggerId, view});
        };

        function route(eventType, event) {
            if (closed || !event || event.subtype || event.bot_id ||
                    typeof event.text !== "string" || typeof event.channel !== "string" ||
                    typeof event.user !== "string") {
                return;
            }
            const channel = (config.channel || "").trim();
            const user = (config.user || "").trim();
            const command = (config.command || "").trim();
            if (channel && event.channel !== channel || user && event.user !== user ||
                    eventType === "slash_command" && command && event.command !== command) {
                return;
            }
            const slack = {
                eventType,
                channel: event.channel,
                user: event.user,
                ts: event.ts || null,
                threadTs: event.thread_ts || null
            };
            if (eventType === "slash_command") {
                slack.command = event.command;
                if (event.interactionId) {
                    slack.socketId = node.id;
                    slack.interactionId = event.interactionId;
                }
            }
            node.send({
                payload: event.text,
                topic: event.channel,
                slack
            });
        }

        const botToken = node.credentials && node.credentials.botToken;
        const appToken = node.credentials && node.credentials.appToken;
        if (!botToken || !appToken) {
            node.status({fill: "red", shape: "ring", text: "Slack tokens required"});
            node.error("Slack Socket Mode requires bot and app tokens");
        } else {
            try {
                app = createApp({token: botToken, appToken, socketMode: true, tokenVerificationEnabled: false});
                app.view(/^nrflow_/, async function({ack, body, view}) {
                    const owner = view && flowForm(view);
                    if (closed || !owner || typeof owner.handleSubmission !== "function") {
                        await ack();
                        return;
                    }
                    await owner.handleSubmission({ack, body, view});
                });
                app.options(/^nrflow_/, async function({ack, options}) {
                    const owner = options && options.view && flowForm(options.view);
                    if (closed || !owner || typeof owner.handleOptions !== "function") {
                        await ack({options: []});
                        return;
                    }
                    await owner.handleOptions({ack, options});
                });
                app.action(/^nrflow_/, async function({ack, action, body, client}) {
                    const owner = body && body.view && flowForm(body.view);
                    await ack();
                    if (!closed && owner && typeof owner.handleAction === "function") {
                        await owner.handleAction({action, body, client});
                    }
                });
                const eventType = config.eventType || "app_mention";
                if (eventType !== "app_mention") {
                    app.message(async ({message}) => route("message", message));
                }
                if (eventType !== "message") {
                    app.event("app_mention", async ({event}) => route("app_mention", event));
                }
                if (config.includeCommands !== false) {
                    app.command(/^\/.+/, async function({command, ack, body}) {
                        await ack();
                        const interactionId = randomUUID();
                        grants.set(interactionId, {
                            triggerId: body && body.trigger_id,
                            user: command.user_id,
                            channel: command.channel_id,
                            command: command.command,
                            expires: Date.now() + 2500
                        });
                        const expiry = setTimeout(() => grants.delete(interactionId), 3000);
                        expiry.unref();
                        route("slash_command", {
                            command: command.command,
                            text: command.text,
                            channel: command.channel_id,
                            user: command.user_id,
                            interactionId
                        });
                    });
                }
                node.status({fill: "yellow", shape: "ring", text: "connecting"});
                Promise.resolve().then(() => app.start()).then(function() {
                    if (closed) {
                        return Promise.resolve().then(() => app.stop()).catch(() => {});
                    }
                    node.status({fill: "green", shape: "dot", text: "connected"});
                }).catch(function() {
                    if (!closed) {
                        node.status({fill: "red", shape: "ring", text: "connection failed"});
                        node.error("Slack Socket Mode could not connect");
                    }
                });
            } catch (error) {
                node.status({fill: "red", shape: "ring", text: "connection failed"});
                node.error("Slack Socket Mode could not initialize");
            }
        }

        node.on("close", function(done) {
            closed = true;
            grants.clear();
            if (!app) {
                done();
                return;
            }
            Promise.resolve().then(() => app.stop()).then(() => done(), () => done());
        });
    }

    RED.nodes.registerType("slack socket", SlackSocketNode, {
        credentials: {
            botToken: {type: "password"},
            appToken: {type: "password"}
        }
    });
};
